CREATE TABLE BOND (
    BOND_ID VARCHAR,
    MOLECULE_ID VARCHAR,
    BOND_TYPE VARCHAR,
    PRIMARY KEY (bond_id),
    FOREIGN KEY (molecule_id) REFERENCES molecule(molecule_id)
);

CREATE TABLE MOLECULE (
    MOLECULE_ID VARCHAR,
    PRIMARY KEY (molecule_id)
);

CREATE TABLE ATOM (
    ATOM_ID VARCHAR,
    MOLECULE_ID VARCHAR,
    ELEMENT VARCHAR,
    PRIMARY KEY (atom_id),
    FOREIGN KEY (molecule_id) REFERENCES molecule(molecule_id)
);

CREATE TABLE MOLECULE (
    MOLECULE_ID VARCHAR,
    LABEL VARCHAR,
    PRIMARY KEY (molecule_id)
);

